\begin{aligned}
4x_1 - x_2 \phantom{{}- x_3} &= 3 \\
-x_1 + 4x_2 - x_3 &= 2 \\
\phantom{-x_1} - x_2 + 4x_3 &= 3
\end{aligned}
\quad \Longrightarrow \quad
\begin{aligned}
x_1 &= (3 + x_2)/4 \\
x_2 &= (2 + x_1 + x_3)/4 \\
x_3 &= (3 + x_2)/4
\end{aligned}

\begin{aligned}
x_1^{(k+1)} &= \frac{1 - x_2^{(k)}}{4} \\
x_2^{(k+1)} &= \frac{2 - 2\,x_1^{(k+1)}}{5} \quad \leftarrow \text{already the new value!}
\end{aligned}
